def e(s):
    return html.escape("" if s is None else str(s), quote=True)

def dv(ru, uk):
    """атрибуты перевода для элемента, внутри которого только текст"""
    return ' data-ru="%s" data-uk="%s"' % (e(ru), e(uk))

def dp(ru, uk):
    """перевод атрибута placeholder"""
    return ' placeholder="%s" data-ru-placeholder="%s" data-uk-placeholder="%s"' % (e(ru), e(ru), e(uk))

def da(ru, uk):
    """перевод атрибута aria-label"""
    return ' aria-label="%s" data-ru-aria="%s" data-uk-aria="%s"' % (e(ru), e(ru), e(uk))

