def etap_po_statusu(st):
    st = (st or "").strip().lower()
    if st.startswith("ua_"):  return "kiev"
    if st.startswith("ge_"):  return "georgia"
    if st.startswith("sea_"): return "sea"
    return "korea"

ETAP_TEXT = {
 "kiev":    ("В Киеве · можно посмотреть", "У Києві · можна оглянути"),
 "georgia": ("В Грузии · финальный этап", "У Грузії · фінальний етап"),
 "sea":     ("В море · Корея → Грузия", "У морі · Корея → Грузія"),
 "korea":   ("Выкуплен и проверен в Корее", "Викуплений і перевірений у Кореї"),
}
