      '<div class="share-control"><button class="share-button" aria-label="Поделиться" aria-expanded="false">%s</button>'
      '<div class="share-menu" hidden><b%s>Поделиться</b>'
      '<a href="[URL]" target="_blank" rel="noopener noreferrer">WhatsApp</a>'
      '<a href="[URL]" target="_blank" rel="noopener noreferrer">Telegram</a>'
      '<button type="button" class="share-copy"%s>Копировать ссылку</button></div>'
      '<span class="share-toast" role="status" hidden></span></div></div>'
      '<div class="vehicle-gallery"><img class="vehicle-main-photo" src="%s" alt="%s" fetchpriority="high" decoding="async">'
      '<div class="thumb-row">%s<span data-vsego="%d">1 / %d</span></div></div>'
      '<div class="lightbox" hidden><button class="lb-close" type="button" aria-label="Закрыть">&#10005;</button>'
      '<button class="lb-prev" type="button" aria-label="Предыдущее фото">&#8249;</button>'
      '<img class="lb-photo" src="" alt="">'
      '<button class="lb-next" type="button" aria-label="Следующее фото">&#8250;</button>'
      '<span class="lb-count"></span></div>'
      '<article class="vehicle-summary"><div><span class="id-chip">%s</span><h1>%s</h1>'
      '<span class="status-pill %s">%s<i%s>%s</i></span></div>'
      '<div class="vehicle-price"><b%s>%s</b><small%s>Под ключ в Киеве · доплат нет</small></div></article>'
      '<section class="spec-card"><span class="section-kicker"%s>КОРОТКО</span><div class="spec-grid">%s</div></section>'
      '<section class="route-card"><div class="section-heading"><div>'
      '<span class="section-kicker"%s>ГДЕ МАШИНА СЕЙЧАС</span><h2%s>Прозрачный маршрут</h2></div></div>'
      '<div class="route-line">%s</div>'
      '<div class="container-data"><p><i%s>Контейнер</i><b%s>%s</b></p>'
      '<p><i%s>Дата отправления</i><b%s>%s</b></p></div>%s%s</section>'
      '<section class="vehicle-actions">'
      '<a class="outline-cta" href="%s-diag.html"><span>&#10003;</span>'
      '<i%s>Комплексная диагностика авто</i>%s</a>'
      '<a class="button gold wide" href="%s" target="_blank" rel="noopener noreferrer"%s>Купить авто</a>'
      '<a class="button ghost wide" href="%s" target="_blank" rel="noopener noreferrer"%s>Задать вопрос</a></section>%s'
    '</section>'
    % (dv("← Все автомобили", "← Усі автомобілі"),
       znak("share"), dv("Поделиться", "Поділитися"),
       e(adres_kartochki), e(adres_kartochki), dv("Копировать ссылку", "Копіювати посилання"),
       e(glavnoe), e(imya), mini, len(kadr_spisok), len(kadr_spisok),
       e(nomer), e(imya),
       "ferry-pill" if etap == "sea" else "", znak(ETAP_ZNAK[etap], 18), dv(st_ru, st_uk), e(st_ru),
       dv(c or "Цена по запросу", c or "Ціна за запитом"), e(c or "Цена по запросу"),
       dv("Под ключ в Киеве · доплат нет", "Під ключ у Києві · доплат немає"),
       dv("КОРОТКО", "КОРОТКО"), spec,
       dv("ГДЕ МАШИНА СЕЙЧАС", "ДЕ АВТО ЗАРАЗ"), dv("Прозрачный маршрут", "Прозорий маршрут"),
