def etap_po_statusu(st):
    st = (st or "").strip().lower()
    if st.startswith("ua_"):  return "kiev"
    if st.startswith("ge_"):  return "georgia"
    if st.startswith("sea_"): return "sea"
    return "korea"

ETAP_TEXT = {
 "kiev":    ("В Киеве · можно посмотреть", "У Києві · можна оглянути"),
 "georgia": ("В Грузии · финальный этап", "У Грузії · фінальний етап"),
 "sea":     ("В море · Корея → Грузия", "У морі · Корея → Грузія"),
 "korea":   ("Выкуплен и проверен в Корее", "Викуплений і перевірений у Кореї"),
}
ETAP_ZNAK = {"kiev": "pin", "georgia": "carrier", "sea": "ferry", "korea": "check"}

def pole(m, *imena):
    for i in imena:
        v = m.get(i)
        if v not in (None, "", "[]", "None"):
            return str(v).strip()
    return ""

def data_iz(s):
    s = (s or "").strip()
    for f in ("%Y-%m-%d", "%d.%m.%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.datetime.strptime(s[:len(datetime.datetime.now().strftime(f))], f).date()
        except Exception:
            continue
    return None

def srok(m):
    """возвращает (вид, дней, дата) — вид: kiev / ozhidanie / otschet / raschet"""
    segodnya = datetime.date.today()
    etap = m["_etap"]
    status = (m.get("status") or "").strip().lower()

    if etap == "kiev":
        return "kiev", 0, None

    # ручная дата администратора имеет высший приоритет
    ruchnaya = data_iz(pole(m, "eta_manual"))
    if ruchnaya:
        return "otschet", max((ruchnaya - segodnya).days, 0), ruchnaya

    # отправлен в Украину: отсчёт только от РЕАЛЬНОЙ даты выезда
    vyehal = data_iz(pole(m, "ge_to_kyiv_at", "ua_departure_at"))
    if vyehal:
        data = vyehal + datetime.timedelta(days=SROK_UKRAINA)
        return "otschet", max((data - segodnya).days, 0), data
    if status.startswith("ge_to_kyiv"):
        return "net_daty", 0, None

    # Грузия без даты отправки — счётчик не запускаем
    if etap == "georgia":
        return "ozhidanie", 0, None

    # Корея и море — расчётный остаток по этапу
    dnej = OSTATOK.get(etap, 85)
    return "raschet", dnej, segodnya + datetime.timedelta(days=dnej)

def data_slovami(d, yazyk="ru"):
    if not d:
        return ""
    mes = MES_RU if yazyk == "ru" else MES_UK
    return "%d %s %d" % (d.day, mes[d.month - 1], d.year)

def kadry(nomer):
    papka = os.path.join(FOTO, nomer)
    if not os.path.isdir(papka):
        return []
    fajly = [f for f in sorted(os.listdir(papka))
             if f.lower().endswith((".jpg", ".jpeg", ".png", ".webp"))]
    return ["%s/%s/%s" % (URL_FOTO, nomer, f) for f in fajly]

def kadry_proverki(nomer):
    papka = os.path.join(DIAG, nomer)
    if not os.path.isdir(papka):
        return [], []
    foto, video = [], []
    for f in sorted(os.listdir(papka)):
        put = os.path.join(papka, f)
        if not os.path.isfile(put):
            continue
        try:
            nachalo = open(put, "rb").read(12)
        except Exception:
            continue
        adres = "%s/%s/%s" % (URL_DIAG, nomer, f)
        if b"ftyp" in nachalo:
            video.append(adres)
        elif nachalo[:3] == b"\xff\xd8\xff" or nachalo[:8] == b"\x89PNG\r\n\x1a\n" or nachalo[8:12] == b"WEBP":
            foto.append(adres)
    return foto, video

def cena(m):
    v = pole(m, "price_uah", "price", "cost_total")
    if not v:
        return None
    chistoe = re.sub(r"[^\d]", "", v)
    if not chistoe:
        return None
    return "{:,}".format(int(chistoe)).replace(",", " ") + " $"

def probeg(m):
    v = pole(m, "mileage_km", "mileage")
    chistoe = re.sub(r"[^\d]", "", v)
    if not chistoe:
        return ""
    return "{:,}".format(int(chistoe)).replace(",", " ") + " км"

def dvigatel(m):
    """1950 -> 1 950 см3 ; 1.8 -> 1,8 л ; значение из базы не округляется"""
    v = pole(m, "engine_cc", "engine")
    chistoe = re.sub(r"[^\d.,]", "", v).replace(",", ".")
    obem = ""
    if chistoe:
        try:
            if "." in chistoe:
                float(chistoe)  # проверка, что это число
                obem = chistoe.replace(".", ",") + " л"
            else:
                chislo = int(chistoe)
                if chislo >= 100:
                    obem = "{:,}".format(chislo).replace(",", "\u00a0") + " см\u00b3"
                else:
                    obem = str(chislo) + " л"
        except Exception:
            obem = v
    else:
        obem = v
    toplivo = pole(m, "fuel")
    return " · ".join([x for x in (obem, toplivo) if x])

def nazvanie(m):
    chasti = [pole(m, "brand"), pole(m, "model"), pole(m, "year")]
    return " ".join([c for c in chasti if c]).strip() or pole(m, "auto_number")

