             e(nazvanie(m)), dv(st_ru, st_uk), e(st_ru), e(stroka_faktov),
             e(nomer), znak("arrow")))

    telo = (
    '<section class="content-page catalog-page">'
      '<div class="page-intro"><span class="section-kicker">КАТАЛОГ</span>'
      '<h1%s>Автомобили в наличии и в пути</h1>'
      '<p%s>Живые фото, прозрачный этап доставки и окончательная цена в Киеве.</p></div>'
      '<div class="filter-row" aria-label="Фильтр по этапу">%s</div>'
      '<p class="catalog-result" aria-live="polite">Показано: %d</p>'
      '<div class="catalog-grid">%s</div>'
      '<div class="empty-assist"><div><span>&#8981;</span>'
      '<h2%s>Не нашли подходящий автомобиль?</h2>'
      '<p%s>Подберём нужную комплектацию и бюджет на зарубежных аукционах.</p></div>'
      '<a class="button gold" href="podbor.html"%s>Подобрать авто</a></div>%s'
    '</section>'
