            schetchik = "—"
            nizhe = ('<div class="diagnostic-status"><span class="green-check">&#9675;</span>'
                     '<span%s>%s</span></div>' % (dv(PUSTO_RU, PUSTO_UK), e(PUSTO_RU)))
        bloki.append(
