    if not kadr_spisok:
        kadr_spisok = ["%s/live/live_korea_UA-0003_002.jpg" % URL_ASSETS]
    glavnoe = kadr_spisok[0]
    mini = "".join(
      '<button type="button" data-n="%d" data-full="%s" class="%s" aria-pressed="%s">'
      '<img src="%s"%s loading="lazy" decoding="async"></button>'
      % (i + 1, e(k), "active" if i == 0 else "", "true" if i == 0 else "false", e(k),
         ' alt="Фото %d" data-ru-alt="Фото %d" data-uk-alt="Фото %d"' % (i + 1, i + 1, i + 1))
      for i, k in enumerate(kadr_spisok))

    harakteristiki = [
      ("speed", "Пробег", "Пробіг", probeg(m)),
      ("engine", "Двигатель", "Двигун", dvigatel(m)),
      ("gear", "Коробка", "Коробка", pole(m, "gearbox")),
      ("drive", "Привод", "Привід", pole(m, "drive")),
      ("paint", "Цвет", "Колір", pole(m, "color")),
      ("vin", "VIN", "VIN", pole(m, "vin")),
    ]
    spec = "".join(
      '<div class="spec-item"><span>%s</span><p><small%s>%s</small><b%s>%s</b></p></div>'
      % (znak(ikonka), dv(ru, uk), e(ru),
         dv(v or "не указано", v or "не вказано"), e(v or "не указано"))
      for ikonka, ru, uk, v in harakteristiki)

    # ролики машины: показываем все, без автозапуска
    # Раздел «Видео автомобиля» есть ВСЕГДА: с роликами лентой или с заглушкой
    roliki = m.get("_video", ([], []))[0]
    if roliki:
        kolvo_ru = "%d %s · листайте вбок" % (len(roliki), sklonenie_video(len(roliki), True))
        kolvo_uk = "%d %s · гортайте вбік" % (len(roliki), sklonenie_video(len(roliki), False))
        kuski_video = ""
        for nomer_r, (adres_r, zastavka_r) in enumerate(roliki, 1):
            kuski_video += ('<figure><video src="%s"%s controls playsinline webkit-playsinline'
                            ' preload="metadata"></video>'
                            '<figcaption%s>Видео автомобиля %d</figcaption>'
                            '<a class="video-otdelno" href="%s" target="_blank" rel="noopener noreferrer"%s>'
