                               (' poster="%s"' % e(zastavka_r)) if zastavka_r else "",
                               dv("Видео автомобиля %d" % nomer_r, "Відео автомобіля %d" % nomer_r),
                               nomer_r, e(adres_r),
                               dv("Открыть видео отдельно", "Відкрити відео окремо")))
        nutro_video = ('<p class="video-schet"%s>%s</p><div class="video-lenta">%s</div>'
                       % (dv(kolvo_ru, kolvo_uk), e(kolvo_ru), kuski_video))
