                       % (dv(VIDEO_PUSTO_RU, VIDEO_PUSTO_UK), e(VIDEO_PUSTO_RU)))
    blok_video = ('<section class="vehicle-video"><span class="section-kicker"%s>ВИДЕО АВТОМОБИЛЯ</span>%s</section>'
                  % (dv("ВИДЕО АВТОМОБИЛЯ", "ВІДЕО АВТОМОБІЛЯ"), nutro_video))

    etap = m["_etap"]
    poryadok = ["korea", "sea", "georgia", "kiev"]
    tochki_ru = ["Корея", "Море", "Грузия", "Киев"]
    tochki_uk = ["Корея", "Море", "Грузія", "Київ"]
