    os.replace(vrem, put)
def sha(put):
    h = hashlib.sha256()
    try:
        with io.open(put, "rb") as f:
            while True:
                b = f.read(524288)
                if not b:
                    break
                h.update(b)
        return h.hexdigest()
    except Exception:
        return ""

