        novyy = re.sub(r'<style id="mcf-chat-css">.*?</style>', "", t, flags=re.S)
        novyy, skolko = MC.obespechit_chat(novyy)
        if novyy != t and len(novyy) > len(t) * 0.9:
            pis(put, novyy)
            izmeneno += 1
pp("4. СТРАНИЦ С ОБНОВЛЁННЫМ ЧАТОМ: %d" % izmeneno)

ind2 = chit(os.path.join(VIDEO, "index.html")) or ""
poz2 = ind2.find("Чат online")
if poz2 < 0:
    poz2 = ind2.find("mcf-chat")
p("ФРАГМЕНТ КНОПКИ ПОСЛЕ ПРАВКИ:")
p("   %s" % (ind2[max(0, poz2 - 180):poz2 + 120].replace("\n", " ") if poz2 >= 0 else "не найдена"))
p("")

# ── повторная пересборка и сверка живых фото
pp("5. ПОВТОРНАЯ ПЕРЕСБОРКА И СВЕРКА ЖИВЫХ ФОТО")
for imya in ("index.html", "katalog.html"):
    for papka in (VIDEO, SITE):
        put = os.path.join(papka, imya)
        t = chit(put)
        if t is None:
            continue
        novyy = MC.obrabotat_obshuyu(t)
        if novyy != t and len(novyy) > len(t) * 0.9:
            pis(put, novyy)

FOTO_POSLE = {}
if os.path.isdir(STAGE):
    for f in sorted(os.listdir(STAGE)):
        FOTO_POSLE[f] = sha(os.path.join(STAGE, f))
izmenilis = [f for f in FOTO_DO if FOTO_DO.get(f) != FOTO_POSLE.get(f)]
propali = [f for f in FOTO_DO if f not in FOTO_POSLE]
pp("   живых фото было %d, стало %d, изменилось %d, пропало %d"
   % (len(FOTO_DO), len(FOTO_POSLE), len(izmenilis), len(propali)))

# ── проверки
chatov = {}
for imya in ("index.html", "katalog.html"):
    t = chit(os.path.join(VIDEO, imya)) or ""
    chatov[imya] = t.count('class="mcf-chat')
for kod in sorted(set(re.findall(r"^(UA-\d{4})\.html$", "\n".join(os.listdir(VIDEO)), re.M))):
    t = chit(os.path.join(VIDEO, "%s.html" % kod)) or ""
    chatov[kod] = t.count('class="mcf-chat')
ploho = [k for k, v in chatov.items() if v != 1]

problemy = []
if izmenilis or propali:
    problemy.append("живые фото изменились: %s" % ", ".join((izmenilis + propali)[:6]))
if ploho:
    problemy.append("чатов не ровно один на: %s" % ", ".join(ploho[:6]))

if problemy:
    pp("6. ПРОБЛЕМЫ — ОТКАТ")
    for x in problemy:
        pp("   %s" % x)
    for imya in os.listdir(BACKUP):
        if imya.endswith(".html"):
            papka = VIDEO if imya.startswith("video_") else SITE
            cel = os.path.join(papka, imya.split("_", 1)[1])
            try:
                shutil.copy2(os.path.join(BACKUP, imya), cel)
            except Exception:
                pass
    shutil.copy2(os.path.join(BACKUP, "master_card.py"), os.path.join(DOM, "master_card.py"))
    itog = "FAIL — %s (всё возвращено из резерва)" % problemy[0]
else:
    pp("6. ПРОВЕРКИ PASS")
    itog = "CHAT MOBILE FIXED — LIVE PHOTO UNCHANGED — CHAT COUNT 1/1"

p("")
p("ИТОГОВЫЕ СТРОКИ")
p("-" * 72)
p("CHAT MOBILE SIZE:        44x44 кружок на экранах до 900 px, desktop не изменён")
p("CHAT COUNT PER PAGE:     %s" % ("1 везде" if not ploho else "нарушено: %s" % ", ".join(ploho)))
p("LIVE PHOTO UNCHANGED:    %s (изменено %d, пропало %d из %d)"
  % ("PASS" if not (izmenilis or propali) else "FAIL",
     len(izmenilis), len(propali), len(FOTO_DO)))
p("LIVE PHOTO AFTER REBUILD: %s"
  % ("PASS — кадры этапов совпадают байт в байт" if not izmenilis else "FAIL"))
