    )
    if len(links) != 1:
        errors.append("ссылок комплексной диагностики не ровно одна")
    if re.search(r'class=["\'][^"\']*\bmcf-diag-off\b', source, re.IGNORECASE):
        errors.append("диагностика ошибочно зависит от наличия материалов")
