            + '<span class="ua-cat-fallback-v1-stage"><span class="ua068-ru">%s</span><span class="ua068-uk">%s</span></span>' % (_ua068_e(labels_ru[stage]), _ua068_e(labels_uk[stage]))
            + _ua068_catalog_block(kod, row)
