        c.append("<div class='blok'><div class='zag'>%s</div>" % ekran(zagolovok))
        stroki = [s.strip() for s in tekst.replace("\r", "").split("\n")]
        stroki = [s for s in stroki if s]
        spiskom = sum(1 for s in stroki if s[:1] in "-–—•*·") >= 2
