    t = "" if t is None else str(t)
    for a, b in (("&", "&amp;"), ("<", "&lt;"), (">", "&gt;"),
                 ('"', "&quot;"), ("'", "&#39;")):
        t = t.replace(a, b)
    return t


def _v170_cena(m):
