# -*- coding: utf-8 -*-
"""
UA ART · ЯДРО ВЁРСТКИ (UA-V177)

Вёрстка по шести утверждённым макетам от 18.08.2026.
Данные — из crm.db и файловой системы. Бот и CRM не затрагиваются.
"""

import io
import os
import re
import json
import time
import html as _html

BAZA = "/home/Carix"
PAPKA_VID = os.path.join(BAZA, "video")
DB = os.path.join(BAZA, "crm.db")
PAMYAT_SROK = os.path.join(BAZA, ".srok_gruzia.json")

ADRES_SAYTA = "https://www.uaart.com.ua/video/"
TELEFON_VID = "[N]"
TELEFON_TEL = "[N]"
WHATSAPP = "[N]"
KARTA_URL = "[URL]"
GOD = "2023"
AVTOGRAF = "BA | Created by Artem Borovinsky"

SROK_GRUZIA = 15
SROK_MORE = 75
SDVIG_KIEV = 7 * 3600

MESYACY_RU = ("января", "февраля", "марта", "апреля", "мая", "июня",
              "июля", "августа", "сентября", "октября", "ноября", "декабря")

METKA_KARTA = "<!--ua-art-karta-v177-->"
METKA_DIAG = "<!--ua-art-diag-v177-->"
METKA_GLAV = "<!--ua-art-glavnaya-v177-->"


def ekran(z):
    return _html.escape("" if z is None else str(z), quote=True)


def t(ru, ua):
    return ("<span data-ru=\"%s\" data-ua=\"%s\">%s</span>"
            % (ekran(ru), ekran(ua), ekran(ru)))


def segodnya_kiev():
    return time.strftime("%Y-%m-%d", time.localtime(time.time() + SDVIG_KIEV))


def razobrat_datu(z):
    z = (z or "").strip()
    if not z:
        return None
    for obr in ("%Y-%m-%d", "%d.%m.%Y", "%Y-%m-%dT%H:%M:%S"):
        try:
            return time.mktime(time.strptime(z[:19], obr))
        except Exception:
            continue
    return None


def data_slovami(metka):
    if metka is None:
        return ""
    d = time.localtime(metka)
    return "%d %s %d" % (d.tm_mday, MESYACY_RU[d.tm_mon - 1], d.tm_year)


def dney_do(metka):
    if metka is None:
        return None
    try:
        a = time.mktime(time.strptime(segodnya_kiev(), "%Y-%m-%d"))
        b = time.mktime(time.strptime(
            time.strftime("%Y-%m-%d", time.localtime(metka)), "%Y-%m-%d"))
        return max(int(round((b - a) / 86400.0)), 0)
    except Exception:
        return None


def sklonenie(n, ukr=False):
    a, b, c = ("день", "дні", "днів") if ukr else ("день", "дня", "дней")
    if n % 10 == 1 and n % 100 != 11:
        return a
    if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14):
        return b
    return c


def dengi(z):
    try:
        n = int(float(z or 0))
    except Exception:
        n = 0
    return "{:,}".format(n).replace(",", " ") + " $" if n > 0 else ""


