def _srok_iz_json(nom):
    try:
        with io.open(PAMYAT_SROK, "r", encoding="utf-8") as f:
            d = json.loads(f.read() or "{}")
        return ((d.get(nom) or {}).get("vyehal") or "").strip()
    except Exception:
        return ""


