ing:14px 20px 18px!important;border:0!important;border-top:1px solid rgba(240,166,60,.32)!important;border-radius:0 0 20px 20px!important;background:var(--ua-card-surface)!important;box-shadow:none!important;}@media(max-width:520px){.catalog-card .ua-cat-vin-v1{padding:13px 20px 17px!important;}}</style>"""
    source = _ua068_re.sub(r'<style\b[^>]*id=["\']ua-cat-vin-v1-style["\'][^>]*>.*?</style\s*>', "", source,
